import React, { useState, useEffect, useRef } from 'react';

const ALEX_AVATAR = "data:image/webp;base64,";

const TEASER_MESSAGES = [
  "👋 Hey! I'm Alex — ask me anything about the opportunity.",
  "🎤 I can speak too — just tap the mic icon!",
  "💰 Want to know what inspectors earn in your city?",
  "🔍 Curious how the AI catches fraud? Ask me!",
  "🚀 I can show you how to get your first client fast.",
];

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

declare global {
  interface Window {
    SpeechRecognition: typeof SpeechRecognition;
    webkitSpeechRecognition: typeof SpeechRecognition;
  }
}

export const SalesChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'assistant', content: "Hey! I'm Alex 👋 I'm here to help you understand the AI Auto Pro opportunity and answer any questions. What's on your mind?" }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [teaserIndex, setTeaserIndex] = useState(0);
  const [showTeaser, setShowTeaser] = useState(false);
  const [teaserVisible, setTeaserVisible] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  useEffect(() => {
    const t = setTimeout(() => {
      if (!isOpen) { setShowTeaser(true); setTimeout(() => setTeaserVisible(true), 50); }
    }, 4000);
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    if (!showTeaser || isOpen) return;
    const interval = setInterval(() => {
      setTeaserVisible(false);
      setTimeout(() => { setTeaserIndex(prev => (prev + 1) % TEASER_MESSAGES.length); setTeaserVisible(true); }, 400);
    }, 5000);
    return () => clearInterval(interval);
  }, [showTeaser, isOpen]);

  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [messages]);

  const sendMessage = async (text: string) => {
    if (!text.trim() || isLoading) return;
    setMessages(prev => [...prev, { role: 'user', content: text }]);
    setInput('');
    setIsLoading(true);
    try {
      const res = await fetch('/api/sales-chat', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: text, history: messages.slice(-6) }),
      });
      const data = await res.json();
      const reply = data.response || "I'm having a quick moment — try again in a second!";
      setMessages(prev => [...prev, { role: 'assistant', content: reply }]);
      speakText(reply);
    } catch {
      setMessages(prev => [...prev, { role: 'assistant', content: "Connection hiccup — try again in a moment!" }]);
    } finally { setIsLoading(false); }
  };

  const speakText = (text: string) => {
    if (!window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const clean = text.replace(/[*_#`]/g, '').substring(0, 300);
    const utterance = new SpeechSynthesisUtterance(clean);
    utterance.rate = 1.05; utterance.pitch = 1.0; utterance.volume = 0.9;
    const voices = window.speechSynthesis.getVoices();
    const preferred = voices.find(v => v.name.includes('Daniel') || v.name.includes('Alex') || v.name.includes('David') || v.name.includes('Google US English'));
    if (preferred) utterance.voice = preferred;
    utterance.onstart = () => setIsSpeaking(true);
    utterance.onend = () => setIsSpeaking(false);
    utterance.onerror = () => setIsSpeaking(false);
    window.speechSynthesis.speak(utterance);
  };

  const stopSpeaking = () => { window.speechSynthesis?.cancel(); setIsSpeaking(false); };

  const startListening = () => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert('Voice input requires Chrome browser.'); return; }
    const recognition = new SR();
    recognition.lang = 'en-US'; recognition.interimResults = false;
    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (e: SpeechRecognitionEvent) => { const t = e.results[0][0].transcript; setInput(t); sendMessage(t); };
    recognition.onend = () => setIsListening(false);
    recognition.onerror = () => setIsListening(false);
    recognitionRef.current = recognition;
    recognition.start();
  };

  const stopListening = () => { recognitionRef.current?.stop(); setIsListening(false); };

  const handleOpen = () => { setIsOpen(true); setShowTeaser(false); setTeaserVisible(false); };

  return (
    <>
      {/* Teaser bubble */}
      {showTeaser && !isOpen && (
        <div style={{ position: 'fixed', bottom: '120px', right: '24px', zIndex: 9999, maxWidth: '260px',
          opacity: teaserVisible ? 1 : 0, transform: teaserVisible ? 'translateY(0) scale(1)' : 'translateY(8px) scale(0.95)',
          transition: 'all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1)', pointerEvents: 'none' }}>
          <div style={{ background: '#fff', borderRadius: '16px 16px 4px 16px', padding: '12px 16px',
            boxShadow: '0 8px 32px rgba(0,0,0,0.3)', fontSize: '13px', color: '#111', fontWeight: 500, lineHeight: 1.4, position: 'relative' }}>
            {TEASER_MESSAGES[teaserIndex]}
            <div style={{ position: 'absolute', bottom: '-8px', right: '20px', width: 0, height: 0,
              borderLeft: '8px solid transparent', borderRight: '8px solid transparent', borderTop: '8px solid #fff' }} />
          </div>
        </div>
      )}

      {/* Floating avatar button */}
      {!isOpen && (
        <button onClick={handleOpen} title="Chat with Alex — AI Sales Consultant"
          style={{ position: 'fixed', bottom: '52px', right: '24px', zIndex: 9999,
            width: '68px', height: '68px', borderRadius: '50%', border: '3px solid #357ABD',
            cursor: 'pointer', padding: 0, overflow: 'visible', background: 'none',
            boxShadow: '0 4px 24px rgba(53,122,189,0.5)',
            animation: 'alexPulse 2.5s ease-in-out infinite' }}>
          <div style={{ width: '100%', height: '100%', borderRadius: '50%', overflow: 'hidden', position: 'relative' }}>
            <img src={ALEX_AVATAR} alt="Alex" style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'top center' }} />
            <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(to top, rgba(10,10,10,0.6) 0%, transparent 55%)',
              display: 'flex', alignItems: 'flex-end', justifyContent: 'center', paddingBottom: '5px' }}>
              <span style={{ fontSize: '9px', color: '#fff', fontWeight: 800, letterSpacing: '0.5px' }}>ALEX</span>
            </div>
          </div>
          {/* Green online dot */}
          <div style={{ position: 'absolute', bottom: '2px', right: '2px', width: '16px', height: '16px',
            borderRadius: '50%', background: '#22c55e', border: '3px solid #0a0a0a',
            animation: 'liveDot 1.8s ease-in-out infinite' }} />
        </button>
      )}

      {/* Chat window */}
      {isOpen && (
        <div style={{ position: 'fixed', bottom: '52px', right: '24px', zIndex: 9999,
          width: '360px', height: '520px', background: '#0d0d0d', borderRadius: '20px',
          border: '1px solid #222', boxShadow: '0 24px 80px rgba(0,0,0,0.7)',
          display: 'flex', flexDirection: 'column', overflow: 'hidden',
          animation: 'slideUp 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)' }}>
          {/* Header */}
          <div style={{ background: 'linear-gradient(135deg, #0f1f35, #0a0a0a)', borderBottom: '1px solid #1a1a1a',
            padding: '14px 16px', display: 'flex', alignItems: 'center', gap: '12px' }}>
            <div style={{ position: 'relative', flexShrink: 0 }}>
              <div style={{ width: '44px', height: '44px', borderRadius: '50%', overflow: 'hidden',
                border: '2px solid #357ABD', boxShadow: '0 0 12px rgba(53,122,189,0.4)' }}>
                <img src={ALEX_AVATAR} alt="Alex" style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'top center' }} />
              </div>
              <div style={{ position: 'absolute', bottom: '1px', right: '1px', width: '12px', height: '12px',
                borderRadius: '50%', background: isSpeaking ? '#f59e0b' : isListening ? '#ef4444' : '#22c55e',
                border: '2px solid #0d0d0d' }} />
            </div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: '15px', fontWeight: 700, color: '#fff' }}>Alex</div>
              <div style={{ fontSize: '11px', color: '#6b9cc8' }}>
                {isSpeaking ? '🔊 Speaking...' : isListening ? '🎤 Listening...' : 'AI Sales Consultant · 🎤 Voice enabled'}
              </div>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
              {isSpeaking && (
                <button onClick={stopSpeaking} style={{ background: 'rgba(239,68,68,0.2)', border: '1px solid rgba(239,68,68,0.4)',
                  borderRadius: '6px', color: '#f87171', cursor: 'pointer', padding: '4px 8px', fontSize: '11px' }}>Stop</button>
              )}
              <button onClick={() => setIsOpen(false)} style={{ background: 'none', border: 'none', color: '#6b9cc8', cursor: 'pointer', fontSize: '22px', lineHeight: 1, padding: '4px' }}>×</button>
            </div>
          </div>

          {/* Messages */}
          <div style={{ flex: 1, overflowY: 'auto', padding: '16px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
            {messages.map((msg, i) => (
              <div key={i} style={{ display: 'flex', gap: '8px', alignItems: 'flex-start', flexDirection: msg.role === 'user' ? 'row-reverse' : 'row' }}>
                {msg.role === 'assistant' && (
                  <div style={{ width: '28px', height: '28px', borderRadius: '50%', overflow: 'hidden', flexShrink: 0, border: '1px solid #357ABD' }}>
                    <img src={ALEX_AVATAR} alt="Alex" style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'top center' }} />
                  </div>
                )}
                <div style={{ maxWidth: '78%',
                  background: msg.role === 'user' ? 'linear-gradient(135deg, #357ABD, #1a5fa0)' : '#1a1a1a',
                  borderRadius: msg.role === 'user' ? '16px 4px 16px 16px' : '4px 16px 16px 16px',
                  padding: '10px 14px', fontSize: '13px', color: '#f0f0f0', lineHeight: 1.55 }}>
                  {msg.content}
                </div>
              </div>
            ))}
            {isLoading && (
              <div style={{ display: 'flex', gap: '8px', alignItems: 'flex-start' }}>
                <div style={{ width: '28px', height: '28px', borderRadius: '50%', overflow: 'hidden', flexShrink: 0, border: '1px solid #357ABD' }}>
                  <img src={ALEX_AVATAR} alt="Alex" style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'top center' }} />
                </div>
                <div style={{ background: '#1a1a1a', borderRadius: '4px 16px 16px 16px', padding: '12px 16px', display: 'flex', gap: '5px', alignItems: 'center' }}>
                  {[0,1,2].map(i => (
                    <div key={i} style={{ width: '6px', height: '6px', borderRadius: '50%', background: '#357ABD', animation: `bounce 1.2s ease-in-out ${i * 0.2}s infinite` }} />
                  ))}
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input */}
          <form onSubmit={e => { e.preventDefault(); sendMessage(input); }}
            style={{ padding: '12px 14px', borderTop: '1px solid #1a1a1a', display: 'flex', gap: '8px', alignItems: 'center', background: '#0a0a0a' }}>
            <input value={input} onChange={e => setInput(e.target.value)}
              placeholder={isListening ? 'Listening...' : 'Ask Alex anything...'}
              disabled={isLoading}
              style={{ flex: 1, background: '#1a1a1a', border: '1px solid #2a2a2a', borderRadius: '12px',
                padding: '10px 14px', color: '#f0f0f0', fontSize: '13px', outline: 'none' }} />
            <button type="button" onClick={isListening ? stopListening : startListening} disabled={isLoading}
              title={isListening ? 'Stop' : 'Speak to Alex'}
              style={{ background: isListening ? 'linear-gradient(135deg, #ef4444, #b91c1c)' : '#1a1a1a',
                border: isListening ? 'none' : '1px solid #2a2a2a', borderRadius: '10px', width: '38px', height: '38px',
                cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
                animation: isListening ? 'micPulse 1s ease-in-out infinite' : 'none' }}>
              <svg width="15" height="15" viewBox="0 0 24 24" fill={isListening ? '#fff' : '#6b9cc8'}>
                <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm-1-9c0-.55.45-1 1-1s1 .45 1 1v6c0 .55-.45 1-1 1s-1-.45-1-1V5zm6 6c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
              </svg>
            </button>
            <button type="submit" disabled={isLoading || !input.trim()}
              style={{ background: input.trim() ? 'linear-gradient(135deg, #357ABD, #1a5fa0)' : '#1a1a1a',
                border: 'none', borderRadius: '10px', width: '38px', height: '38px',
                cursor: input.trim() ? 'pointer' : 'default',
                display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <line x1="22" y1="2" x2="11" y2="13" />
                <polygon points="22 2 15 22 11 13 2 9 22 2" />
              </svg>
            </button>
          </form>
        </div>
      )}

      <style>{`
        @keyframes alexPulse {
          0%, 100% { box-shadow: 0 4px 24px rgba(53,122,189,0.5), 0 0 0 0 rgba(53,122,189,0.35); }
          50% { box-shadow: 0 4px 24px rgba(53,122,189,0.7), 0 0 0 14px rgba(53,122,189,0); }
        }
        @keyframes liveDot {
          0%, 100% { opacity: 1; transform: scale(1); }
          50% { opacity: 0.4; transform: scale(0.75); }
        }
        @keyframes slideUp {
          from { opacity: 0; transform: translateY(20px) scale(0.95); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes bounce {
          0%, 60%, 100% { transform: translateY(0); }
          30% { transform: translateY(-5px); }
        }
        @keyframes micPulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.55; }
        }
      `}</style>
    </>
  );
};

export default SalesChatWidget;
